<script setup lang="ts">
import StatusProgress from './StatusProgress.vue'
defineProps<{ dashboard:any; money:(value:number)=>string; date:(value?:string)=>string }>()
const emit=defineEmits<{filter:[value:string]}>()
const bar=(value:number, rows:any[])=>`${Math.max(6,Math.round(value/Math.max(...rows.map(x=>Number(x.count)||0),1)*100))}%`
</script>
<template><section class="metrics"><article v-for="metric in [{label:'MONTHLY VALUE',value:money(dashboard?.monthSummary?.[0]?.total)},{label:'RECORDS TODAY',value:dashboard?.recordsToday||0},{label:'ACTIVE RECORDS',value:dashboard?.activeRecords||0},{label:'UPCOMING EVENTS',value:dashboard?.upcomingEvents?.length||0}]" :key="metric.label"><span>{{metric.label}}</span><strong>{{metric.value}}</strong><small>Updated from your records</small></article></section><section class="grid"><article class="card"><h2>Activity over the last 30 days</h2><svg v-if="dashboard?.last30Days?.length" viewBox="0 0 300 110" preserveAspectRatio="none"><rect v-for="(d,i) in dashboard.last30Days" :key="d.record_date" :x="i*(300/dashboard.last30Days.length)" :y="110-Number(bar(d.count,dashboard.last30Days).replace('%',''))*1.1" :width="Math.max(3,280/dashboard.last30Days.length)" :height="Number(bar(d.count,dashboard.last30Days).replace('%',''))*1.1" rx="2"/></svg><p v-else>No activity yet</p></article><article class="card"><h2>Record status</h2><StatusProgress v-for="s in dashboard?.byStatus||[]" :key="s.name" :name="s.name" :color="s.color" :count="s.count" :total="dashboard?.activeRecords||0"/></article><article class="card"><h2>Unpaid invoices</h2><strong>{{dashboard?.unpaidCount||0}}</strong><button @click="emit('filter','unpaid')">View records</button></article><article class="card"><h2>Needs delivery</h2><strong>{{dashboard?.deliveryCount||0}}</strong><button @click="emit('filter','delivery')">View records</button></article></section></template>
<style scoped>.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:18px}.metrics article,.card{background:var(--card);border:1px solid var(--border);border-radius:12px;padding:20px}.metrics span,.metrics small{display:block;color:var(--muted)}.metrics strong{display:block;font-size:25px;margin:9px 0}.grid{display:grid;grid-template-columns:1.5fr 1fr;gap:16px}.card h2{margin:0 0 12px;font-size:16px}.card strong{font-size:26px}.card button{border:0;background:none;color:var(--brand);font-weight:800;cursor:pointer;padding:8px 0}svg{width:100%;height:130px;background:#f6f1e8;border-radius:8px}rect{fill:var(--brand)}@media(max-width:900px){.metrics{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr}}</style>
